$root = (Resolve-Path "$PSScriptRoot\..\..").Path; if (-not $env:AVATARKIT_HOME) { $env:AVATARKIT_HOME = Join-Path $root '.avatarkit' }; foreach ($name in 'cache','temp') { $path = Join-Path $env:AVATARKIT_HOME $name; if (Test-Path $path) { Get-ChildItem -Force $path | Remove-Item -Recurse -Force } }; Write-Host 'Cleared AvatarKit cache and temporary files only.'
